SELECT CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, MAX(orders.shipping_fee) - MIN(orders.shipping_fee) AS shipping_fee_range, SUM(CASE WHEN orders.status = 'SHIPPED' THEN orders.amount ELSE 0 END) AS shipped_amount FROM orders INNER JOIN stores ON orders.store_id = stores.id INNER JOIN customers ON orders.customer_id = customers.id GROUP BY CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY shipping_fee_range DESC, opened_cohort LIMIT 10
